1	"use client";
2	
3	import { useEffect, useRef, useState, useReducer } from "react";
4	import {
5	  ChatBubbleLeftRightIcon,
6	  XMarkIcon,
7	  PaperAirplaneIcon,
8	  ArrowPathIcon,
9	} from "@heroicons/react/24/outline";
10	import Turn from "./turn";
11	import { ChatTurn } from "@/lib/types";
12	import { useSession } from "next-auth/react";
13	import { sendChatMessage } from "@/lib/messaging";
14	import { ACTION_BOUNDARY, FIELD_BOUNDARY } from "@/lib/control-classes";
15	
16	interface ChatAction {
17	  type: "add" | "clear" | "resolve";
18	  payload?: ChatTurn;
19	  id?: string;
20	}
21	
22	interface ChatState {
23	  turns: ChatTurn[];
24	}
25	
26	function chatReducer(state: ChatState, action: ChatAction) {
27	  switch (action.type) {
28	    case "add":
29	      return { turns: [...state.turns, action.payload!] };
30	    case "clear":
31	      return { turns: [] };
32	    case "resolve": {
33	      // Replace the placeholder this reply owns. If it is not present — the
34	      // thread was reset, or it never appeared because the reply was fast —
35	      // append instead, so no other turn is overwritten.
36	      const index = state.turns.findIndex((turn) => turn.id === action.id);
37	      if (index === -1) return { turns: [...state.turns, action.payload!] };
38	      const turns = [...state.turns];
39	      turns[index] = action.payload!;
40	      return { turns };
41	    }
42	    default:
43	      throw new Error();
44	  }
45	}
46	
47	export const Chat = () => {
48	  const { data: session } = useSession();
49	  const [showChat, setShowChat] = useState(false);
50	  const [message, setMessage] = useState("");
51	
52	  const [state, dispatch] = useReducer(chatReducer, { turns: [] });
53	
54	  const chatDiv = useRef<HTMLDivElement>(null);
55	  const inputRef = useRef<HTMLInputElement>(null);
56	  const panelRef = useRef<HTMLDivElement>(null);
57	  const launcherRef = useRef<HTMLButtonElement>(null);
58	  const widgetRef = useRef<HTMLDivElement>(null);
59	  const greetingTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
60	  // Why the panel last closed, read by the focus-return effect below.
61	  const closedByFocusOut = useRef(false);
62	  // Whether the panel is open *now*, for callbacks that were created while it
63	  // was. A reply outlives the send that started it.
64	  const showChatRef = useRef(false);
65	
66	  // Below `lg` the panel is a full-screen sheet, so it really does contain the
67	  // user and says so. At `lg` and up it occupies a corner, the rest of the page
68	  // is usable, and trapping focus would take the site navigation away.
69	  //
70	  // `false` until mounted, so the server and the first client render agree.
71	  // Only the semantics depend on this; the sheet itself is `max-lg:` CSS and is
72	  // right from first paint whether or not this has run.
73	  const [isCompact, setIsCompact] = useState(false);
74	
75	  // What a reply announces when there is no panel to announce it in. See the
76	  // effect below.
77	  const [announcement, setAnnouncement] = useState("");
78	
79	  // The exact complement of Tailwind's `lg:`, expressed as its own query rather
80	  // than a `max-width` with an epsilon, so a fractional viewport cannot land
81	  // between the two and satisfy neither. `tailwind.config.ts` sets no `screens`
82	  // override, so 1024px is Tailwind's default and these two must move together.
83	  //
84	  // `lg` rather than `sm`, which is where #129 first drew it, because a card is
85	  // only a card if the page is still there around it. Measured with the panel
86	  // open: it covers 72% of the viewport at 640, 75% at 768 and 70% at 834 —
87	  // against 40% at 1440. The three widths in that band were failing 2.4.11 the
88	  // same way 390 was, one breakpoint up. See #183.
89	  useEffect(() => {
90	    const query = window.matchMedia("(min-width: 1024px)");
91	    const sync = () => setIsCompact(!query.matches);
92	    sync();
93	    query.addEventListener("change", sync);
94	    return () => query.removeEventListener("change", sync);
95	  }, []);
96	
97	  const isModal = showChat && isCompact;
98	
99	  // The other three parts of being modal. All of them keyed on `isModal`, so a
100	  // resize past the breakpoint with the panel open moves it between the two
101	  // contracts rather than stranding it half-way — `aria-modal` without a trap
102	  // tells assistive technology something false, and a trap without `inert`
103	  // leaves the covered controls clickable.
104	
105	  // Everything beside the widget, found through the DOM rather than by tag: the
106	  // widget's siblings are whatever the root layout puts next to it, and naming
107	  // `main` here would silently stop covering the page the day that changes.
108	  useEffect(() => {
109	    if (!isModal) return;
110	    const parent = widgetRef.current?.parentElement;
111	    if (!parent) return;
112	    const behind = Array.from(parent.children).filter(
113	      (child): child is HTMLElement =>
114	        child instanceof HTMLElement && child !== widgetRef.current
115	    );
116	    behind.forEach((element) => element.setAttribute("inert", ""));
117	    return () => behind.forEach((element) => element.removeAttribute("inert"));
118	  }, [isModal]);
119	
120	  // `inert` blocks pointer and focus but not scrolling, so without this the
121	  // page slides around behind a sheet that covers all of it.
122	  useEffect(() => {
123	    if (!isModal) return;
124	    const previous = document.body.style.overflow;
125	    document.body.style.overflow = "hidden";
126	    return () => {
127	      document.body.style.overflow = previous;
128	    };
129	  }, [isModal]);
130	
131	  // The trap covers the widget, not the panel: the launcher sits outside the
132	  // dialog and is the close control, so a trap scoped to `panelRef` would make
133	  // the one thing that dismisses the sheet the one thing Tab cannot reach.
134	  //
135	  // What this is for is narrower than it looks. `inert` above is what keeps
136	  // focus off the obscured page — those elements leave the tab order entirely —
137	  // so containment is not this block's job and the e2e spec's "nothing escaped
138	  // the widget" assertion stays green without it. Measured, not assumed.
139	  //
140	  // What is covered: both wrap branches, by `wraps focus at both ends of the
141	  // sheet` in chat.test.tsx, and their absence at desktop by `does not trap
142	  // focus at lg and up`. Delete this effect and those go red.
143	  //
144	  // What is not covered by anything: the recovery branch below, for focus that
145	  // is already outside the widget — removing that alone leaves the whole suite
146	  // green. Nor is the case it exists for, Tab from the last control stepping
147	  // into the browser's own chrome rather than back to the top of the sheet,
148	  // which Playwright cannot see because it never leaves the page. Nor is
149	  // degradation where `inert` is unsupported, which is the only reason
150	  // containment does not rest on a single API.
151	  useEffect(() => {
152	    if (!isModal) return;
153	    const onKeyDown = (event: KeyboardEvent) => {
154	      if (event.key !== "Tab") return;
155	      const widget = widgetRef.current;
156	      if (!widget) return;
157	      const focusable = Array.from(
158	        widget.querySelectorAll<HTMLElement>(
159	          'a[href], button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
160	        )
161	      );
162	      if (focusable.length === 0) return;
163	      const first = focusable[0];
164	      const last = focusable[focusable.length - 1];
165	      const active = document.activeElement;
166	
167	      // Focus already outside the widget — a click on inert content cannot put
168	      // it there, but the address bar can — so the next Tab returns rather than
169	      // continuing through the page.
170	      if (!widget.contains(active)) {
171	        event.preventDefault();
172	        (event.shiftKey ? last : first).focus();
173	        return;
174	      }
175	      if (event.shiftKey && active === first) {
176	        event.preventDefault();
177	        last.focus();
178	      } else if (!event.shiftKey && active === last) {
179	        event.preventDefault();
180	        first.focus();
181	      }
182	    };
183	    document.addEventListener("keydown", onKeyDown);
184	    return () => document.removeEventListener("keydown", onKeyDown);
185	  }, [isModal]);
186	
187	  // At `lg` and up the panel stays non-modal, and non-modal is a claim that the
188	  // page behind is still usable. It is not quite: the card still covers 30-54%
189	  // of the viewport there, and at 1440 four product links sit entirely behind
190	  // it. Nothing can scroll them clear — they are ~400px tall and the panel
191	  // leaves 12px above it and 100px below, so there is nowhere to scroll them
192	  // to. Shrinking the panel does not fix it either: what is hidden depends on
193	  // where the grid puts links, not on the panel's area (1280 measures 0 hidden
194	  // and 1440 measures 4).
195	  //
196	  // So the panel gets out of the way instead of pretending it already has.
197	  // Keyboard only, and the criterion is too: 2.4.11 is about the *focused*
198	  // control, and focus is the thing this can observe. A mouse user still cannot
199	  // reach what the card covers — 6 of 22 product links at 1440 and 7 of 22 at
200	  // 1024, at some scroll position — because clicking bare page fires no
201	  // `focusin` and the panel stays up. That is #187, not this.
202	  //
203	  // Nothing focused can be obscured behind a panel that is gone, and the
204	  // conversation is not lost — the turns live in the reducer, so reopening
205	  // restores the thread rather than starting a new one. See #183.
206	  //
207	  // Only where it is not modal: below `lg` the surrounding page is `inert`, so
208	  // focus cannot land there in the first place, and this would be dead code
209	  // that closes the sheet on nothing.
210	  //
211	  // Backwards only, deliberately. The widget is last in the document, so Tab
212	  // forward off its final control leaves the page entirely: no `focusin` fires,
213	  // and the panel stays up until focus re-enters at the top, one keystroke
214	  // later. That stop is the browser's own chrome — the address bar — and
215	  // dismissing the panel while the user is up there would be closing it for
216	  // something that is not a page interaction at all.
217	  useEffect(() => {
218	    if (!showChat || isCompact) return;
219	    const onFocusIn = (event: FocusEvent) => {
220	      const target = event.target as Node | null;
221	      if (target && widgetRef.current?.contains(target)) return;
222	      // Focus has already moved to where the user asked for it. Say so, or the
223	      // focus-return effect below reads this as an ordinary close and drags
224	      // focus back onto the launcher they were leaving.
225	      closedByFocusOut.current = true;
226	      setShowChat(false);
227	    };
228	    document.addEventListener("focusin", onFocusIn);
229	    return () => document.removeEventListener("focusin", onFocusIn);
230	  }, [showChat, isCompact]);
231	
232	  useEffect(() => {
233	    showChatRef.current = showChat;
234	  }, [showChat]);
235	
236	  // Cancel an unfired greeting whenever the panel closes, by whatever route.
237	  // The open branch of `toggleChat` guards on `turns.length`, but a pending
238	  // timer has not dispatched yet, so closing and reopening inside 400ms — an
239	  // ordinary impatient tap — schedules a second timer and both fire.
240	  //
241	  // Here rather than in `toggleChat`, which is where it used to live and only
242	  // ever covered the button. Escape has always had the same hole, and closing
243	  // on focus-out would have been a third way in. Measured, all three closed
244	  // within 400ms and reopened: button one greeting, Escape two, focus-out two.
245	  // One place, so a fourth close path cannot reintroduce it.
246	  useEffect(() => {
247	    if (showChat) return;
248	    if (greetingTimer.current) clearTimeout(greetingTimer.current);
249	  }, [showChat]);
250	
251	  // Opening the panel left focus on the launcher, so the next Tab continued
252	  // into the page behind it rather than into the conversation.
253	  useEffect(() => {
254	    if (showChat) inputRef.current?.focus();
255	  }, [showChat]);
256	
257	  // Focus return, after the close rather than during it. Below `lg` the
258	  // launcher is unmounted while the sheet is open, so a `focus()` inside the
259	  // close handler runs against an element that is not in the document yet and
260	  // silently drops focus to <body> — which is the bug moving focus in on open
261	  // was added to fix, in the other direction. One mechanism rather than two, so
262	  // both the Escape path and the button path go through here.
263	  // Returned on an explicit dismissal — Escape, or the close button — and only
264	  // then. A close caused by focus leaving the panel already has focus on the
265	  // control the user moved to, and pulling it back onto the launcher undoes
266	  // their keystroke: one Shift+Tab would close the panel, scroll to the link
267	  // they reached, and then take focus off it again, leaving them where they
268	  // started with the scroll position gone. That is WCAG 3.2.1 On Focus, and the
269	  // widget is last in the document, so Shift+Tab is the only way out.
270	  const wasOpen = useRef(false);
271	  useEffect(() => {
272	    if (wasOpen.current && !showChat && !closedByFocusOut.current) {
273	      launcherRef.current?.focus();
274	    }
275	    closedByFocusOut.current = false;
276	    wasOpen.current = showChat;
277	  }, [showChat]);
278	
279	  // Crossing the breakpoint unmounts whichever close control belonged to the
280	  // side being left — the sheet's header button on the way up, the launcher on
281	  // the way down. With focus parked on it, focus falls to <body> and the next
282	  // Tab restarts at the top of the document, which is the failure this
283	  // component has already fixed on open and on close, arriving by a third
284	  // route. Declared after the two effects above so it sees where they left
285	  // focus rather than racing them.
286	  useEffect(() => {
287	    if (!showChat) return;
288	    if (widgetRef.current?.contains(document.activeElement)) return;
289	    panelRef.current?.focus();
290	  }, [isCompact, showChat]);
291	
292	  // Bound to the document so Escape works wherever focus sits inside the
293	  // panel, but scoped to events originating within it. Unscoped, Escape while
294	  // the site's nav drawer was open dismissed the chat underneath it and left
295	  // the drawer up — closing the layer the user was not interacting with.
296	  useEffect(() => {
297	    if (!showChat) return;
298	    const onKeyDown = (event: KeyboardEvent) => {
299	      if (event.key !== "Escape") return;
300	      const target = event.target as Node;
301	      const inPanel = panelRef.current?.contains(target);
302	      const onLauncher = launcherRef.current === target;
303	      if (!inPanel && !onLauncher) return;
304	      setShowChat(false);
305	    };
306	    document.addEventListener("keydown", onKeyDown);
307	    return () => document.removeEventListener("keydown", onKeyDown);
308	  }, [showChat]);
309	
310	  const scrollChat = () => {
311	    setTimeout(() => {
312	      if (chatDiv.current) {
313	        chatDiv.current.scrollTo({
314	          top: chatDiv.current.scrollHeight,
315	          behavior: "smooth",
316	        });
317	      }
318	    }, 10);
319	  };
320	
321	  useEffect(() => {
322	    scrollChat();
323	  }, [state.turns.length]);
324	
325	  // Ids of sends whose replies this thread still wants. A reset empties it, so
326	  // anything already in flight is abandoned rather than landing in a
327	  // conversation the user cleared.
328	  const pendingIds = useRef<Set<string>>(new Set());
329	
330	  const greeting = (): ChatTurn => ({
331	    name: "Jane Doe",
332	    message: `Hi ${session?.user?.name || "there"}, how can I be helpful today?`,
333	    status: "done",
334	    type: "assistant",
335	    avatar: "",
336	  });
337	
338	  const reset = () => {
339	    setMessage("");
340	    pendingIds.current.clear();
341	    dispatch({ type: "clear" });
342	    // Cancel the timer toggleChat queued. Resetting within 400ms of opening
343	    // otherwise seeds the greeting here and again when that timer fires.
344	    if (greetingTimer.current) clearTimeout(greetingTimer.current);
345	    // Re-seed rather than leaving the panel blank. The greeting only rendered
346	    // on open, so a cleared thread stayed empty for the rest of the session —
347	    // a state that was unreachable while the reset control was not a control.
348	    dispatch({ type: "add", payload: greeting() });
349	    inputRef.current?.focus();
350	  };
351	
352	  const sendMessage = () => {
353	    // Trimmed: the guard was `message === ""`, so three spaces and Enter fired
354	    // a real request and rendered an empty bubble. Before anything is minted —
355	    // registering a pending id for a send that never happens leaves an entry
356	    // nothing can remove, so the set stops meaning "replies still wanted".
357	    const question = message.trim();
358	    if (question === "") return;
359	
360	    const userName = session?.user?.name || "Guest";
361	    const userAvatar = (session?.user as any)?.image || "";
362	    const customerId = (session?.user as any)?.id;
363	
364	    const newTurn: ChatTurn = {
365	      name: userName,
366	      message: question,
367	      status: "done",
368	      type: "user",
369	      avatar: userAvatar,
370	    };
371	
372	    // Each send owns a placeholder identified by id. Positional replacement
373	    // breaks as soon as two sends overlap, because "the last turn" may belong
374	    // to the other request — the reply then overwrites a turn it does not own
375	    // and the other placeholder spins forever.
376	    const pendingId = `pending-${Date.now()}-${Math.random().toString(36).slice(2)}`;
377	    pendingIds.current.add(pendingId);
378	
379	    const showPlaceholder = () =>
380	      setTimeout(() => {
381	        // Membership covers both cases: the reply already settled, or the
382	        // thread was reset. Either way this placeholder has no owner.
383	        if (!pendingIds.current.has(pendingId)) return;
384	        dispatch({
385	          type: "add",
386	          payload: {
387	            id: pendingId,
388	            name: "Jane Doe",
389	            message: "Let me see what I can find...",
390	            status: "waiting",
391	            type: "assistant",
392	            avatar: "",
393	          },
394	        });
395	      }, 400);
396	
397	    const settle = (timer: ReturnType<typeof setTimeout>) => (responseTurn: ChatTurn) => {
398	      clearTimeout(timer);
399	      // Two jobs in one call. The return value is the guard: a reset between
400	      // the request and its reply removed the id, so the reply is dropped
401	      // rather than appended into the cleared thread as an answer to nothing.
402	      // The removal itself is hygiene — ids are unique, so a settled one left
403	      // behind changes no behaviour, it just accumulates for the lifetime of
404	      // the panel, which is mounted once in the root layout.
405	      if (!pendingIds.current.delete(pendingId)) return;
406	      dispatch({ type: "resolve", id: pendingId, payload: responseTurn });
407	
408	      // The panel's `role="log"` is what tells a screen-reader user an answer
409	      // arrived, and closing on focus-out unmounts it mid-request. The turn
410	      // still lands — this line ran — but with the log gone nothing says so,
411	      // and asking a question then tabbing back into the page to keep browsing
412	      // is what a non-modal panel is for. This change made that reachable, so
413	      // it has to cover it.
414	      //
415	      // Here rather than in an effect watching `state.turns`: this is the
416	      // moment a reply arrives, so there is no "did it arrive while closed?"
417	      // to reconstruct, and no `setState` in an effect body to cascade from.
418	      if (!showChatRef.current) {
419	        setAnnouncement("Jane Doe replied. Open chat to read the answer.");
420	      }
421	    };
422	
423	    // sendChatMessage resolves with an error turn rather than rejecting, but a
424	    // rejection would otherwise leave the placeholder spinning with no message.
425	    const settleWithError =
426	      (timer: ReturnType<typeof setTimeout>) => (error: unknown) => {
427	        console.error("Chat request failed:", error);
428	        settle(timer)({
429	          id: pendingId,
430	          name: "Jane Doe",
431	          message: "Sorry, something went wrong. Please try again.",
432	          status: "done",
433	          type: "assistant",
434	          avatar: "",
435	        });
436	      };
437	
438	    const send = (request: Promise<ChatTurn>) => {
439	      const timer = showPlaceholder();
440	      request.then(settle(timer)).catch(settleWithError(timer));
441	    };
442	
443	    dispatch({ type: "add", payload: newTurn });
444	    send(sendChatMessage(newTurn, customerId));
445	
446	    setMessage("");
447	  };
448	
449	  const toggleChat = () => {
450	    setShowChat(!showChat);
451	
452	    if (showChat) {
453	      // Closing dropped focus to <body>, so the next Tab restarted at the top
454	      // of the document — 24 stops back to this launcher. Moving focus in on
455	      // open is only half the contract. Returned by the effect above, which
456	      // runs after the launcher is back in the document.
457	      return;
458	    }
459	
460	    // Opening is reading: the announcement has served its purpose, and leaving
461	    // it in the live region means the next reply that repeats it is a text
462	    // change of nothing and may not be announced at all.
463	    setAnnouncement("");
464	
465	    scrollChat();
466	    if (state.turns.length === 0) {
467	      greetingTimer.current = setTimeout(() => {
468	        dispatch({ type: "add", payload: greeting() });
469	      }, 400);
470	    }
471	  };
472	
473	  return (
474	    <>
475	      <div
476	        ref={widgetRef}
477	        className="fixed bottom-0 right-0 mr-4 mb-4 sm:mr-12 sm:mb-12 z-10 flex flex-col items-end"
478	      >
479	        {showChat && (
480	          // Two shapes, not one shape with overrides. Below `lg` a sheet, at
481	          // `lg` and up a card, and the two sets of classes do not intersect —
482	          // a base radius that a max-width variant has to win against
483	          // depends on which variant Tailwind emits later, which is not
484	          // something this file should be betting on.
485	          //
486	          // Width was a flat w-[650px]. At 390px the panel rendered at
487	          // left:-308, clipping message text outside the viewport entirely.
488	          // dvh rather than vh so mobile browser chrome does not push the input
489	          // below the fold, and `top`/`height` rather than `inset-0` so the two
490	          // do not over-constrain each other.
491	          <div
492	            ref={panelRef}
493	            role="dialog"
494	            aria-label="Chat with Jane Doe"
495	            // Only where it is true. `role="dialog"` is not a claim of
496	            // containment; this is.
497	            aria-modal={isCompact ? true : undefined}
498	            tabIndex={-1}
499	            className="flex flex-col bg-white outline-none
500	                       max-lg:fixed max-lg:inset-x-0 max-lg:top-0
501	                       max-lg:h-[100dvh] max-lg:w-full
502	                       lg:mb-3 lg:shadow-md lg:rounded-lg
503	                       lg:w-[min(650px,calc(100vw-7rem))]
504	                       lg:h-[calc(100vh-7rem)]"
505	          >
506	            <div className="p-2 flex items-center gap-1 mx-auto w-full max-w-2xl max-lg:border-b max-lg:border-zinc-200">
507	              {/*
508	                A sheet has to introduce itself. A corner card can borrow
509	                identity from the page around it; this one has covered that
510	                page, and without a title the whole surface carried no heading
511	                at all while the document behind it had eight.
512	              */}
513	              {isCompact && (
514	                <h2 className="pl-2 grow text-base font-semibold text-zinc-900">
515	                  Chat with Jane Doe
516	                </h2>
517	              )}
518	              <button
519	                type="button"
520	                onClick={reset}
521	                aria-label="Clear conversation"
522	                className="ml-auto p-2 rounded-md hover:bg-zinc-100 hover:cursor-pointer focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sky-700"
523	              >
524	                <ArrowPathIcon className="w-5 stroke-zinc-500" aria-hidden="true" />
525	              </button>
526	              {/*
527	                Dismissal belongs in the header on a sheet, and rendered on
528	                `isCompact` rather than hidden with `sm:hidden` so that exactly
529	                one control is named "Close chat" at any width — two would be
530	                ambiguous to a screen reader and unaddressable by name in tests,
531	                and a CSS-hidden one is still present in jsdom, where no
532	                stylesheet runs.
533	
534	                It also un-crowds the bottom right. The launcher used to float
535	                over the sheet 20px below the send button: two icon-only
536	                controls of near-identical size in one column, where a mis-tap
537	                discards the message being composed.
538	              */}
539	              {isCompact && (
540	                <button
541	                  type="button"
