import { chromium } from 'playwright'

const BASE = process.env.BASE ?? 'http://127.0.0.1:3177'
const WIDTH = Number(process.env.WIDTH ?? 1280)
const HEIGHT = Number(process.env.HEIGHT ?? 720)

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: WIDTH, height: HEIGHT } })

page.on('pageerror', (e) => console.log('PAGEERROR:', e.message))
page.on('console', (m) => {
  const t = m.text()
  if (t.startsWith('TRACE')) console.log(t)
})

await page.goto(`${BASE}/contact`, { waitUntil: 'networkidle' })

// Instrument before the click: record every dialog mount/unmount and every
// focus movement, in order, with the element that received it.
await page.evaluate(() => {
  const name = (n) =>
    !n || n.nodeType !== 1
      ? String(n && n.nodeName)
      : `${n.tagName.toLowerCase()}${n.id ? '#' + n.id : ''}${
          n.getAttribute && n.getAttribute('aria-label')
            ? '[' + n.getAttribute('aria-label') + ']'
            : ''
        }`

  window.__trace = []
  const log = (s) => {
    window.__trace.push(s)
    console.log('TRACE ' + s)
  }

  for (const type of ['focusin', 'focusout']) {
    document.addEventListener(
      type,
      (e) => log(`${type} target=${name(e.target)} related=${name(e.relatedTarget)}`),
      true
    )
  }

  new MutationObserver((records) => {
    for (const r of records) {
      for (const n of r.addedNodes)
        if (n.nodeType === 1 && (n.matches?.('[role=dialog]') || n.querySelector?.('[role=dialog]')))
          log('dialog ADDED')
      for (const n of r.removedNodes)
        if (n.nodeType === 1 && (n.matches?.('[role=dialog]') || n.querySelector?.('[role=dialog]')))
          log('dialog REMOVED')
    }
  }).observe(document.body, { childList: true, subtree: true })
})

const launcher = page.getByRole('button', { name: 'Open chat' })
console.log('launcher visible:', await launcher.isVisible())

await launcher.click()
await page.waitForTimeout(1500)

const state = await page.evaluate(() => ({
  dialogs: document.querySelectorAll('[role=dialog]').length,
  chatInput: document.querySelectorAll('#chat').length,
  openLauncher: document.querySelectorAll('[aria-label="Open chat"]').length,
  closeLauncher: document.querySelectorAll('[aria-label="Close chat"]').length,
  active: document.activeElement?.tagName + '/' + (document.activeElement?.id || ''),
  trace: window.__trace,
}))

console.log('--- after click ---')
console.log(JSON.stringify(state, null, 2))

await browser.close()

import { chromium } from '@playwright/test'

const BASE = process.env.BASE ?? 'http://127.0.0.1:3177'
const PATH = process.env.PATH_ ?? '/contact'
const WIDTH = Number(process.env.WIDTH ?? 1280)
const HEIGHT = Number(process.env.HEIGHT ?? 720)

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: WIDTH, height: HEIGHT } })

page.on('pageerror', (e) => console.log('PAGEERROR:', e.message.split('\n')[0]))
page.on('console', (m) => console.log(`CONSOLE[${m.type()}]:`, m.text().slice(0, 300)))

await page.goto(`${BASE}${PATH}`, { waitUntil: 'networkidle' })
await page.waitForTimeout(2000)

// Did React attach at all, and did this component's effects run?
const probe = await page.evaluate(() => {
  const launcher = document.querySelector('[aria-label="Open chat"]')
  const key = launcher && Object.keys(launcher).find((k) => k.startsWith('__react'))
  return {
    hasNextRouter: typeof window.next !== 'undefined',
    launcherFound: !!launcher,
    reactFiberKeys: launcher ? Object.keys(launcher).filter((k) => k.startsWith('__react')) : [],
    hasReactProps: !!key,
    bodyOverflow: document.body.style.overflow,
  }
})
console.log('PROBE:', JSON.stringify(probe, null, 2))

// Does a *different* client component on this page respond to a real event?
// The contact form's controlled input is the issue's hydration evidence; a
// controlled input also accepts typing with no React attached, so this asks
// for something only a React handler can do.
const beforeClick = await page.evaluate(
  () => document.querySelector('[aria-label="Open chat"]')?.getAttribute('aria-label')
)
await page.getByRole('button', { name: 'Open chat' }).click()
await page.waitForTimeout(1000)
const afterClick = await page.evaluate(() => ({
  label:
    document.querySelector('[aria-label="Open chat"]')?.getAttribute('aria-label') ??
    document.querySelector('[aria-label="Close chat"]')?.getAttribute('aria-label'),
  dialogs: document.querySelectorAll('[role=dialog]').length,
}))
console.log('label before click:', beforeClick, '-> after:', JSON.stringify(afterClick))

await browser.close()

