import { spawn, type ChildProcess } from 'node:child_process'
import { createServer } from 'node:net'
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import path from 'node:path'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'

/**
 * The dev server has to serve `/_next/*` to a browser that reached it over the
 * loopback address.
 *
 * Next's dev server blocks cross-origin requests to its own internal routes,
 * and the allowlist it compares against is `localhost`, `**.localhost` and the
 * hostname the server was bound with -- `127.0.0.1` is in none of those. So a
 * dev server opened at `http://127.0.0.1:<port>` answered 403 to three of its
 * client chunks, React never hydrated, and every client component on the page
 * was inert. Clicking the chat launcher did nothing, which is how #228 was
 * reported: the panel looked broken, and the component was fine.
 *
 * Asserted against a running server rather than against `next.config.js`,
 * because the config key is the request and the status code is what was
 * produced. The two come apart on a Next upgrade that renames the key, retires
 * the gate, or changes what the default allowlist already covers, and in every
 * one of those cases reading the config still passes.
 *
 * The probe path deliberately names no real chunk. The gate runs before
 * routing, on any `/_next/*` URL, so an asset that does not exist separates
 * the two answers cleanly: blocked is 403, allowed is 404. Chunk names are
 * content-hashed and would otherwise have to be scraped from the page first,
 * which means compiling it, for an assertion that never needed the bytes.
 *
 * `foreign origin is still blocked` is the control. Without it this file
 * passes just as well against a dev server with the gate disabled outright,
 * which is a different change from the one that was made and a worse one --
 * and it is also what proves the probe reaches the gate at all, rather than
 * 404ing for some reason of its own.
 */

const WEB_DIR = fileURLToPath(new URL('.', import.meta.url))
const PROBE = '/_next/static/chunks/probe-no-such-chunk.js'

/**
 * `next dev` rewrites this on boot: the paths it imports are derived from
 * `distDir`, which differs between dev and build. It is tracked, so a test that
 * starts a dev server has to put it back or `make test` leaves the tree dirty.
 * That churn is not this change's -- see the issue linked from the pull request.
 */
const GENERATED = path.join(WEB_DIR, 'next-env.d.ts')

async function freePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const probe = createServer()
    probe.on('error', reject)
    probe.listen(0, '127.0.0.1', () => {
      const address = probe.address()
      if (typeof address === 'string' || address === null) {
        reject(new Error('no port assigned'))
        return
      }
      probe.close(() => resolve(address.port))
    })
  })
}

async function statusFor(port: number, origin?: string): Promise<number> {
  const response = await fetch(`http://127.0.0.1:${port}${PROBE}`, {
    headers: origin ? { Origin: origin } : {},
  })
  // Drain, or the agent keeps the socket open and the suite hangs on exit.
  await response.arrayBuffer()
  return response.status
}

async function waitForServer(port: number, child: ChildProcess): Promise<void> {
  const deadline = Date.now() + 90_000
  while (Date.now() < deadline) {
    if (child.exitCode !== null) {
      throw new Error(`next dev exited early with code ${child.exitCode}`)
    }
    try {
      await statusFor(port)
      return
    } catch {
      await new Promise((resolve) => setTimeout(resolve, 250))
    }
  }
  throw new Error('next dev did not become reachable within 90s')
}

describe('next dev cross-origin gate', () => {
  let child: ChildProcess
  let port: number
  let generatedBefore: string

  beforeAll(async () => {
    generatedBefore = readFileSync(GENERATED, 'utf8')
    port = await freePort()
    child = spawn('npx', ['next', 'dev', '-p', String(port)], {
      cwd: WEB_DIR,
      // Its own process group, so the whole tree goes down with it below.
      detached: true,
      stdio: 'ignore',
      env: { ...process.env, PORT: undefined, BROWSER: 'none' } as NodeJS.ProcessEnv,
    })
    await waitForServer(port, child)
  }, 120_000)

  afterAll(async () => {
    if (child?.pid) {
      try {
        process.kill(-child.pid, 'SIGTERM')
      } catch {
        // Already gone.
      }
    }
    writeFileSync(GENERATED, generatedBefore)
  })

  it('serves an internal route to a browser on 127.0.0.1', async () => {
    expect(await statusFor(port, `http://127.0.0.1:${port}`)).toBe(404)
  })

  it('serves an internal route to a browser on localhost', async () => {
    expect(await statusFor(port, `http://localhost:${port}`)).toBe(404)
  })

  it('still blocks a foreign origin', async () => {
    expect(await statusFor(port, 'http://evil.example')).toBe(403)
  })
})

