// every boot. That file is this repository's authoritative runbook for coding
// agents and is written by hand -- a tool appending instructions to it is the
// one thing `AGENTS.md` says must not happen, and the appended text asks to
// be committed along with whatever change was in flight. It also rewrote the
// file underneath the guard in `next-dev-origins.test.ts`, which starts a dev
// server.
agentRules: false,

images: {
  deviceSizes,
},

