import { chromium } from '@playwright/test'

const browser = await chromium.launch()

for (const base of ['http://127.0.0.1:3178', 'http://localhost:3178']) {
  for (const [label, viewport] of [
    ['phone 390x844', { width: 390, height: 844 }],
    ['desktop 1280x720', { width: 1280, height: 720 }],
  ]) {
    const page = await browser.newPage({ viewport })
    let forbidden = 0
    page.on('response', (r) => {
      if (r.status() === 403) forbidden++
    })
    await page.goto(`${base}/contact`, { waitUntil: 'networkidle' })
    await page.waitForTimeout(1000)

    const hydrated = await page.evaluate(() => {
      const l = document.querySelector('[aria-label="Open chat"]')
      return !!l && Object.keys(l).some((k) => k.startsWith('__react'))
    })

    await page.getByRole('button', { name: 'Open chat' }).click()
    await page.waitForTimeout(900)

    const after = await page.evaluate(() => ({
      dialogs: document.querySelectorAll('[role=dialog]').length,
      input: document.querySelectorAll('#chat').length,
      focused: document.activeElement?.id || document.activeElement?.tagName,
      modal: document.querySelector('[role=dialog]')?.getAttribute('aria-modal'),
    }))

    // And it stays open rather than closing itself, which is what #228 guessed
    // was happening.
    await page.waitForTimeout(1200)
    const stillOpen = await page.evaluate(
      () => document.querySelectorAll('[role=dialog]').length
    )

    console.log(
      `${base.padEnd(22)} ${label.padEnd(18)} 403s=${forbidden} hydrated=${hydrated} ` +
        `dialog=${after.dialogs} input=${after.input} focus=${after.focused} ` +
        `aria-modal=${after.modal} stillOpenAfter1.2s=${stillOpen}`
    )
    await page.close()
  }
}

await browser.close()

