 * between dev and build, so it rewrites them in one direction and `next build`
 * rewrites them back. Without this, `make test` leaves a dirty tree and the
 * pre-commit hook picks the churn up as though it were part of the change.
 *
 * The churn itself is not this change's and is not fixed here -- see the issue
 * linked from the pull request. `AGENTS.md` was a third until `agentRules:
 * false` in `next.config.js` stopped it being written at all, which is why that
 * one is a fix and these two are a restore.
 */
const REGENERATED = ['next-env.d.ts', 'tsconfig.json'].map((name) =>
  path.join(WEB_DIR, name)
)

async function freePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const probe = createServer()
    probe.on('error', reject)
    probe.listen(0, '127.0.0.1', () => {
      const address = probe.address()
      if (typeof address === 'string' || address === null) {
        reject(new Error('no port assigned'))
        return
      }
      probe.close(() => resolve(address.port))
    })
  })
}

async function statusFor(port: number, origin?: string): Promise<number> {
  const response = await fetch(`http://127.0.0.1:${port}${PROBE}`, {
    headers: origin ? { Origin: origin } : {},
  })
  // Drain, or the agent keeps the socket open and the suite hangs on exit.
  await response.arrayBuffer()
  return response.status
}

async function waitForServer(port: number, child: ChildProcess): Promise<void> {
  const deadline = Date.now() + 90_000
  while (Date.now() < deadline) {
    if (child.exitCode !== null) {
      throw new Error(`next dev exited early with code ${child.exitCode}`)
    }
    try {
      await statusFor(port)
      return
    } catch {
      await new Promise((resolve) => setTimeout(resolve, 250))
    }
  }
  throw new Error('next dev did not become reachable within 90s')
}

describe('next dev cross-origin gate', () => {
  let child: ChildProcess
  let port: number
  let before: string[]

  beforeAll(async () => {
    before = REGENERATED.map((file) => readFileSync(file, 'utf8'))
    port = await freePort()
    child = spawn('npx', ['next', 'dev', '-p', String(port)], {
      cwd: WEB_DIR,
      // Its own process group, so the whole tree goes down with it below.
      detached: true,
      stdio: 'ignore',
      env: { ...process.env, PORT: undefined, BROWSER: 'none' } as NodeJS.ProcessEnv,
    })
    await waitForServer(port, child)
  }, 120_000)

  afterAll(async () => {
    if (child?.pid) {
      try {
        process.kill(-child.pid, 'SIGTERM')
      } catch {
        // Already gone.
      }
    }
    // After the server is down, so nothing it writes on the way out lands
    // after the restore.
    await new Promise((resolve) => setTimeout(resolve, 250))
    REGENERATED.forEach((file, index) => writeFileSync(file, before[index]))
  })

  it('serves an internal route to a browser on 127.0.0.1', async () => {
    expect(await statusFor(port, `http://127.0.0.1:${port}`)).toBe(404)
  })

  it('serves an internal route to a browser on localhost', async () => {
    expect(await statusFor(port, `http://localhost:${port}`)).toBe(404)
  })

  it('still blocks a foreign origin', async () => {
    expect(await statusFor(port, 'http://evil.example')).toBe(403)
  })
})

