import { chromium } from '@playwright/test'

const browser = await chromium.launch()
for (const base of ['http://[::1]:3178', 'http://127.0.0.1:3178']) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } })
  let forbidden = 0
  page.on('response', (r) => {
    if (r.status() === 403) forbidden++
  })
  await page.goto(`${base}/contact`, { waitUntil: 'networkidle' })
  await page.waitForTimeout(800)
  const hydrated = await page.evaluate(() => {
    const l = document.querySelector('[aria-label="Open chat"]')
    return !!l && Object.keys(l).some((k) => k.startsWith('__react'))
  })
  await page.getByRole('button', { name: 'Open chat' }).click()
  await page.waitForTimeout(700)
  const dialogs = await page.evaluate(() => document.querySelectorAll('[role=dialog]').length)
  console.log(`${base.padEnd(22)} 403s=${forbidden} hydrated=${hydrated} dialog=${dialogs}`)
  await page.close()
}
await browser.close()

